/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('SpaceGrotesk');

// Load clean sans-serif font for the Monolith branding
const { fontFamily } = loadFont();



export type MonolithAnimationProps = Record<string, any>;

const MonolithAnimation: React.FC<MonolithAnimationProps> = ({
  backgroundColor = "#F9F8F6",
  transparentBackground = false,
  durationInSeconds = 8,
  monolithColor = "#2D3238",
  monolithExtrusionColor = "#1D2125",
  textColor = "#FFFFFF",
  numberOfArrows = 100,
  shakingIntensity = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;

  // Prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Geometry calculations
  const mw = width * 0.38; // Monolith width
  const mh = height * 0.65; // Monolith height
  const cx = width * 0.52; // Centered position slightly to the right to accommodate extrusion
  const cy = height * 0.5;
  const extrusionDepth = Math.min(width, height) * 0.045; // Depth of 3D face

  // Front face bounds (static baseline)
  const fL = cx - mw / 2;
  const fR = cx + mw / 2;
  const fT = cy - mh / 2;
  const fB = cy + mh / 2;

  // Timing markers based on frame proportion
  const monolithSpawnFrame = 0;
  const arrowsStartFrame = 12;
  const shakeStartFrame = Math.floor(totalFrames * 0.35); // Shaking builds
  const crackStartFrame = Math.floor(totalFrames * 0.55); // Crack develops
  const peakIntensityFrame = Math.floor(totalFrames * 0.8); // Violent phase

  // Monolith Spawn Animation (Spring entry from bottom)
  const spawnSpring = spring({
    frame: frame - monolithSpawnFrame,
    fps,
    config: { damping: 12, mass: 1.2, stiffness: 90 },
  });
  const monolithYOffset = interpolate(spawnSpring, [0, 1], [height * 0.8, 0]);
  const monolithScale = interpolate(spawnSpring, [0, 1], [0.85, 1]);

  // Shaking progress curve
  const shakeProgress = interpolate(
    frame,
    [shakeStartFrame, crackStartFrame, peakIntensityFrame, totalFrames],
    [0, 0.25, 1.0, 1.0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Eratic deterministic shaking coordinates
  const shakeFreqX1 = 1.3;
  const shakeFreqX2 = 2.7;
  const shakeFreqY1 = 1.1;
  const shakeFreqY2 = 2.4;
  
  const shakeX = shakeProgress > 0 
    ? (Math.sin(frame * shakeFreqX1) * 0.7 + Math.cos(frame * shakeFreqX2) * 0.3) * shakingIntensity * shakeProgress
    : 0;
  const shakeY = shakeProgress > 0 
    ? (Math.cos(frame * shakeFreqY1) * 0.7 + Math.sin(frame * shakeFreqY2) * 0.3) * shakingIntensity * shakeProgress
    : 0;

  // Generate deterministic messy arrows using useMemo for stability
  const arrows = useMemo(() => {
    const list = [];
    const half = Math.floor(numberOfArrows / 2);
    const arrowColors = ["#7C5DAB", "#4E9FE5", "#F37053", "#F2BC3F", "#E05A75", "#69B37E"];

    // Left incoming arrows (point to the left face)
    for (let i = 0; i < half; i++) {
      const seed = `left-arrow-${i}`;
      const startY = interpolate(random(`${seed}-y`), [0, 1], [height * 0.05, height * 0.95]);
      const targetY = interpolate(random(`${seed}-ty`), [0, 1], [fT + mh * 0.08, fB - mh * 0.08]);
      
      // Control points to create messy tangled loops/curves
      const cp1x = interpolate(random(`${seed}-cp1x`), [0, 1], [width * 0.05, width * 0.28]);
      const cp1y = interpolate(random(`${seed}-cp1y`), [0, 1], [height * -0.15, height * 1.15]);
      const cp2x = interpolate(random(`${seed}-cp2x`), [0, 1], [width * 0.18, width * 0.32]);
      const cp2y = targetY; // Ensures horizontal impact straight on the edge

      const color = arrowColors[Math.floor(random(`${seed}-color`) * arrowColors.length)];
      const strokeWidth = interpolate(random(`${seed}-sw`), [0, 1], [2.5, 5.5]);
      const stagger = interpolate(random(`${seed}-stagger`), [0, 1], [0, 30]);

      list.push({
        side: "left" as const,
        startX: -width * 0.1,
        startY,
        targetX: fL,
        targetY,
        cp1x,
        cp1y,
        cp2x,
        cp2y,
        color,
        strokeWidth,
        stagger,
      });
    }

    // Right incoming arrows (point to the right extruded side face)
    for (let i = 0; i < half; i++) {
      const seed = `right-arrow-${i}`;
      const startY = interpolate(random(`${seed}-y`), [0, 1], [height * 0.05, height * 0.95]);
      // Lands on the right face projection
      const targetY = interpolate(random(`${seed}-ty`), [0, 1], [fT + mh * 0.12, fB - mh * 0.12]);

      const cp1x = interpolate(random(`${seed}-cp1x`), [0, 1], [width * 0.72, width * 0.95]);
      const cp1y = interpolate(random(`${seed}-cp1y`), [0, 1], [height * -0.15, height * 1.15]);
      const cp2x = interpolate(random(`${seed}-cp2x`), [0, 1], [width * 0.65, width * 0.82]);
      const cp2y = targetY; // Horizontal impact

      const color = arrowColors[Math.floor(random(`${seed}-color`) * arrowColors.length)];
      const strokeWidth = interpolate(random(`${seed}-sw`), [0, 1], [2.5, 5.5]);
      const stagger = interpolate(random(`${seed}-stagger`), [0, 1], [5, 35]);

      list.push({
        side: "right" as const,
        startX: width * 1.1,
        startY,
        targetX: fR + extrusionDepth,
        targetY: targetY + extrusionDepth * 0.3, // Adjust for the extrusion projection offset
        cp1x,
        cp1y,
        cp2x,
        cp2y,
        color,
        strokeWidth,
        stagger,
      });
    }

    return list;
  }, [numberOfArrows, width, height, fL, fR, fT, fB, mh, extrusionDepth]);

  // Crack development animation
  const crackProgress = interpolate(
    frame,
    [crackStartFrame, peakIntensityFrame],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Jagged crack coordinates starting from the top-right corner moving downwards
  const crackPoints = useMemo(() => {
    return [
      { x: fR - mw * 0.22, y: fT },
      { x: fR - mw * 0.20, y: fT + mh * 0.1 },
      { x: fR - mw * 0.30, y: fT + mh * 0.22 },
      { x: fR - mw * 0.26, y: fT + mh * 0.34 },
      { x: fR - mw * 0.35, y: fT + mh * 0.48 },
      { x: fR - mw * 0.32, y: fT + mh * 0.62 },
      { x: fR - mw * 0.38, y: fT + mh * 0.76 },
    ];
  }, [fR, fT, mw, mh]);

  // Build the SVG path for the crack
  const crackPathD = useMemo(() => {
    return crackPoints.reduce((acc, pt, idx) => {
      return idx === 0 ? `M ${pt.x} ${pt.y}` : `${acc} L ${pt.x} ${pt.y}`;
    }, "");
  }, [crackPoints]);

  // Secondary side crack branching off
  const branchCrackPathD = useMemo(() => {
    const startPt = crackPoints[3];
    return `M ${startPt.x} ${startPt.y} L ${startPt.x + mw * 0.08} ${startPt.y + mh * 0.08} L ${startPt.x + mw * 0.05} ${startPt.y + mh * 0.18}`;
  }, [crackPoints, mw, mh]);

  // Chipped bottom corner path (dark cutaway)
  const bottomChipPath = `
    M ${fR - mw * 0.08} ${fB} 
    L ${fR - mw * 0.06} ${fB - mh * 0.06} 
    L ${fR - mw * 0.01} ${fB - mh * 0.04} 
    L ${fR} ${fB} Z
  `;

  // Deterministic debris particles breaking off
  const debrisParticles = useMemo(() => {
    const list = [];
    const baseReleaseFrame = crackStartFrame + 15;
    for (let i = 0; i < 7; i++) {
      const seed = `debris-${i}`;
      const startX = fR - mw * 0.05 + interpolate(random(`${seed}-x`), [0, 1], [-20, 10]);
      const startY = fB - mh * 0.02 + interpolate(random(`${seed}-y`), [0, 1], [-10, 10]);
      const size = interpolate(random(`${seed}-size`), [0, 1], [4, 12]);
      const targetDeltaX = interpolate(random(`${seed}-tdx`), [0, 1], [-80, 80]);
      const fallHeight = interpolate(random(`${seed}-fh`), [0, 1], [150, 300]);
      
      list.push({
        startX,
        startY,
        size,
        targetDeltaX,
        fallHeight,
        releaseFrame: baseReleaseFrame + i * 6,
      });
    }
    return list;
  }, [fR, fB, mw, mh, crackStartFrame]);

  // Render hand-drawn dynamic vibration wiggle lines (only active during peak shake)
  const renderWiggleLines = () => {
    if (shakeProgress < 0.2) return null;
    const isEven = Math.floor(frame / 3) % 2 === 0;
    const wiggleOpacity = interpolate(shakeProgress, [0.2, 0.8], [0, 0.85]);

    return (
      <g style={{ opacity: wiggleOpacity, stroke: "#1A1D20", strokeWidth: 2.5, fill: "none", strokeLinecap: "round" }}>
        {isEven ? (
          <>
            {/* Set A */}
            <path d={`M ${fL - 25} ${fT + 30} Q ${fL - 40} ${fT + 50} ${fL - 25} ${fT + 70}`} />
            <path d={`M ${fL - 15} ${fT + 40} Q ${fL - 28} ${fT + 50} ${fL - 15} ${fT + 60}`} />
            <path d={`M ${fR + extrusionDepth + 25} ${fB - 50} Q ${fR + extrusionDepth + 40} ${fB - 30} ${fR + extrusionDepth + 25} ${fB - 10}`} />
          </>
        ) : (
          <>
            {/* Set B (slightly offset to simulate hand-drawn flicker) */}
            <path d={`M ${fL - 28} ${fT + 27} Q ${fL - 38} ${fT + 52} ${fL - 28} ${fT + 68}`} />
            <path d={`M ${fL - 18} ${fT + 38} Q ${fL - 26} ${fT + 48} ${fL - 18} ${fT + 58}`} />
            <path d={`M ${fR + extrusionDepth + 28} ${fB - 47} Q ${fR + extrusionDepth + 38} ${fB - 33} ${fR + extrusionDepth + 28} ${fB - 13}`} />
          </>
        )}
      </g>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, overflow: "hidden" }}>
      <svg
        style={{
          width: "100%",
          height: "100%",
          position: "absolute",
          top: 0,
          left: 0,
        }}
      >
        {/* Soft shadow below the block */}
        <ellipse
          cx={cx + shakeX}
          cy={fB + 18 + shakeY}
          rx={(mw / 2) * 1.05 * monolithScale}
          ry={16 * monolithScale}
          fill="rgba(0, 0, 0, 0.12)"
          style={{ transform: `scale(${monolithScale})`, transformOrigin: `${cx}px ${cy}px`, transition: "none" }}
        />

        {/* ==================== MESSY INCOMING ARROWS ==================== */}
        <g>
          {arrows.map((line, idx) => {
            // Stagger start timing
            const arrowDrawProgress = interpolate(
              frame,
              [arrowsStartFrame + line.stagger, arrowsStartFrame + line.stagger + 25],
              [1, 0],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            // Animate dynamic frantic wiggle based on overall network tension
            const wiggleAmp = shakeProgress * 15;
            const wave = Math.sin(frame * 0.22 + idx) * wiggleAmp;
            
            // Build bezier path string
            const pathD = `M ${line.startX} ${line.startY} C ${line.cp1x} ${line.cp1y + wave} ${line.cp2x} ${line.cp2y + wave} ${line.targetX + shakeX} ${line.targetY + shakeY}`;

            // Arrow head polygon alignment
            const isLeft = line.side === "left";
            const headSize = 10;
            const ax = line.targetX + shakeX;
            const ay = line.targetY + shakeY;
            
            // Vertices pointing horizontal directly to impact point
            const arrowHeadPoints = isLeft
              ? `${ax},${ay} ${ax - headSize * 1.5},${ay - headSize * 0.9} ${ax - headSize * 1.2},${ay} ${ax - headSize * 1.5},${ay + headSize * 0.9}`
              : `${ax},${ay} ${ax + headSize * 1.5},${ay - headSize * 0.9} ${ax + headSize * 1.2},${ay} ${ax + headSize * 1.5},${ay + headSize * 0.9}`;

            return (
              <g key={`arrow-${idx}`} style={{ transition: "none" }}>
                {/* Drawn Path */}
                <path
                  d={pathD}
                  fill="none"
                  stroke={line.color}
                  strokeWidth={line.strokeWidth}
                  strokeLinecap="round"
                  strokeDasharray="1400"
                  strokeDashoffset={arrowDrawProgress * 1400}
                />
                {/* Impact Arrowhead */}
                {arrowDrawProgress === 0 && (
                  <polygon
                    points={arrowHeadPoints}
                    fill={line.color}
                    style={{ transition: "none" }}
                  />
                )}
              </g>
            );
          })}
        </g>

        {/* ==================== THE MONOLITH BLOCK ==================== */}
        <g
          style={{
            transform: `translate(${shakeX}px, ${shakeY}px) scale(${monolithScale})`,
            transformOrigin: `${cx}px ${cy}px`,
            transition: "none",
          }}
        >
          {/* 3D Extruded Right Side Face */}
          <path
            d={`
              M ${fR} ${fT + 12}
              L ${fR + extrusionDepth} ${fT + 12 + extrusionDepth * 0.35}
              L ${fR + extrusionDepth} ${fB - 12 + extrusionDepth * 0.35}
              L ${fR} ${fB - 12}
              Z
            `}
            fill={monolithExtrusionColor}
            stroke="#16181C"
            strokeWidth={3}
            strokeLinejoin="round"
          />

          {/* Front Monolith Rounded Face */}
          <rect
            x={fL}
            y={fT}
            width={mw}
            height={mh}
            rx={20}
            fill={monolithColor}
            stroke="#1E2125"
            strokeWidth={4.5}
          />

          {/* ==================== GRAPHICS / LOGO / TEXT ==================== */}
          <text
            x={cx}
            y={cy + 15}
            fill={textColor}
            fontSize={78}
            fontWeight="bold"
            letterSpacing={1.5}
            textAnchor="middle"
            style={{
              fontFamily,
              userSelect: "none",
              filter: "drop-shadow(0px 3px 6px rgba(0,0,0,0.45))",
            }}
          >
            Monolith
          </text>

          {/* ==================== INTERNAL DEVASTATING CRACKS ==================== */}
          {/* Subtle 3D structural outline shadow of crack (depth visual) */}
          <path
            d={crackPathD}
            fill="none"
            stroke="rgba(255, 255, 255, 0.12)"
            strokeWidth={7}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray="900"
            strokeDashoffset={900 * (1 - crackProgress)}
            style={{ transform: "translate(2px, 1.5px)" }}
          />

          {/* Primary Crack Path (Gravel/Empty void space inside stone) */}
          <path
            d={crackPathD}
            fill="none"
            stroke="#121417"
            strokeWidth={5}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray="900"
            strokeDashoffset={900 * (1 - crackProgress)}
          />

          {/* Hairline highlight highlighting crack sharpness */}
          <path
            d={crackPathD}
            fill="none"
            stroke="#1A1D21"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray="900"
            strokeDashoffset={900 * (1 - crackProgress)}
            style={{ transform: "translate(-1px, -1px)" }}
          />

          {/* Secondary Branching Crack */}
          {crackProgress > 0.45 && (
            <path
              d={branchCrackPathD}
              fill="none"
              stroke="#121417"
              strokeWidth={3.5}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray="400"
              strokeDashoffset={400 * (1 - interpolate(crackProgress, [0.45, 1], [0, 1]))}
            />
          )}

          {/* Structural Failure Cut / Chip out (bottom right corner) */}
          {crackProgress > 0.75 && (
            <path
              d={bottomChipPath}
              fill="#121417"
              stroke="#1A1D21"
              strokeWidth={3}
            />
          )}

          {/* Hand drawn shake guidelines surrounding monolith */}
          {renderWiggleLines()}
        </g>

        {/* ==================== CRUMBLING FRAGMENTS & DEBRIS ==================== */}
        <g>
          {debrisParticles.map((pt, idx) => {
            if (frame < pt.releaseFrame) return null;

            // Physics of collapsing debris
            const particleLife = 38; // frames of falling
            const progress = interpolate(
              frame,
              [pt.releaseFrame, pt.releaseFrame + particleLife],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            // X offset starts at monolith bottom edge and spreads out slightly
            const curX = interpolate(progress, [0, 1], [pt.startX, pt.startX + pt.targetDeltaX]);
            
            // Gravity parabolic arc: Y = startY + (progress * fallHeight) + gravity effect
            const curY = interpolate(progress, [0, 1], [pt.startY, pt.startY + pt.fallHeight]);
            
            // Rotation speed
            const rotation = interpolate(progress, [0, 1], [0, idx % 2 === 0 ? 360 : -360]);
            
            // Disintegrate (fade) as they near the bottom
            const opacity = interpolate(progress, [0.75, 1], [1, 0]);

            return (
              <polygon
                key={`debris-${idx}`}
                points={`
                  ${curX},${curY - pt.size / 2} 
                  ${curX + pt.size / 2},${curY + pt.size / 2} 
                  ${curX - pt.size / 2},${curY + pt.size / 3}
                `}
                fill={monolithColor}
                stroke="#121417"
                strokeWidth={1.5}
                opacity={opacity}
                style={{
                  transform: `rotate(${rotation}deg)`,
                  transformOrigin: `${curX}px ${curY}px`,
                  transition: "none",
                }}
              />
            );
          })}
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default MonolithAnimation;